catalog_script_client.script:
function onLoad() {
    applyLiveMask('v_receita_corrente_liquida');
    applyLiveMask('v_investimento_empenhado');
    applyLiveMask('v_investimento_liquidado');
    applyLiveMask('v_investimento_pago');

}

function applyLiveMask(variableName) {
    var field = g_form.getControl(variableName);
    if (!field) return;

    field.addEventListener('input', function(e) {
        var raw = field.value.replace(/[^\d]/g, '');
        if (!raw) {
            field.value = '';
            return;
        }
        var number = parseFloat(raw) / 100;
        var formatted = number.toLocaleString('pt-BR', {
            style: 'currency',
            currency: 'BRL'
        });
        field.value = formatted;
        field.setSelectionRange(formatted.length, formatted.length);
    });

    field.addEventListener('paste', function(e) {
        var pasted = (e.clipboardData || window.clipboardData).getData('text');
        if (/[^\d]/.test(pasted.replace(/[^\d]/g, ''))) {
            e.preventDefault();
        }
    });
}
